custom_css:
/* <十四行诗> 作者by点心 Discord@老实人豁出去了 禁止二传二售 基本都在开头的变量中调整 */

/* ===== 全局样式 ===== */

/* 装饰引用字体 */
@import url("https://fontsapi.zeoseven.com/285/main/result.css");

/* 正文字体 */
@import url("https://fontsapi.zeoseven.com/415/main/result.css");

#chat .mes_block {
    font-family: "WenYuan Serif SC VF";
    font-weight: 500;
}

/* 全局变量 */
:root {
    --font-second: "Noto Serif CJK", "Noto Serif SC", "Source Han Serif SC", "Source Han Serif CN", serif;
    --font-second-weight: 500;

    --mycolor: rgb(206, 142, 167);  /* 主题颜色 */

    /* ▶气泡相关◀ */
    --mesandmes: 32px;  /* 上下气泡之间的距离 */
    --mes-bottom: 50px;  /* 气泡与底栏之间的距离 */
    --mes-border-radius: 10px;  /* 气泡四个圆角大小 */

    /* ▶正文相关◀ */
    --text-padding-lr: 12px;  /* 📱正文文字与气泡左右边缘的距离 pc端找💻标识 */
    --text-padding-top: 12px;  /* 正文文字与名字/思维链的距离 */
    --text-padding-bottom: 42px;  /* 正文文字与气泡底部的距离 一般要留出切换消息按钮的距离 */

    /* ▶头像相关◀ */
    --ava-ratio: 5 / 3;  /* 头像的宽高比例 不要去掉斜杠左右的空格！可以改成你喜欢的比例 */
    --mesAva-width: 92%;  /* 📱头像宽度 其实也就是等比例修改大小 pc端找💻标识 */
    --ava-area: 40%;  /* 头像的显示区域改这里的40% */
    --ava-top: 68px;  /* 头像距气泡顶部的距离 */
    --ava-border-radius: 0px;  /* 头像圆角大小 配合1:1比例时 改为50%是圆形 */
    --ava-border-w: 1px;  /* 头像边框粗细 */
    --ava-border-color: rgba(255, 255, 255, 0.5);  /* 头像边框颜色 */

    /* ▶楼层计时器字符器相关◀ */
    --IdTimerToken-color: var(--SmartThemeUnderlineColor);
    --IdTimerToken-top: 4px;  /* 控制楼层 用时 tokens上下 */
    --IdTimerToken-between: 28px;  /* 控制楼层 用时 tokens之间的距离 */
    --IdTimerToken-fs: 12px;  /* 控制楼层 用时 tokens字体大小 */
    --line-top: 0px;  /* 控制楼层下面的横线上下 */
    --line-width: var(--mesAva-width);  /* 楼层等下面的横线，随头像大小变化，宽度可自行更改 */

    /* ▶名字相关◀ */
    --name-left: 40px;  /* 📱名字左右 pc端找💻标识 */
    --name-top: 28px;  /* 名字上下 */
    --name-fs: 1.8em;  /* 名字大小 */
    --name-color: var(--SmartThemeBodyColor);  /* 名字颜色 */
    --name-width: 55%;  /* 名字区域的宽度 */

    /* ▶名字底下的方块装饰相关◀ */
    --namebefore-left: 24px;  /* 装饰左右 */
    --namebefore-top: -10px;  /* 装饰上下 */
    --namebefore-width: calc(100% + 8px);  /* 装饰宽度 */
    --namebefore-height: 80%;  /* 装饰高度 */
    --namebefore-color: color-mix(in srgb, var(--mycolor), transparent 88%);  /* 装饰颜色 */

    --chnameright-padding: var(--text-padding-lr);  /* DIY文字 小铅笔 时间 与右侧边距离 改成calc((100vw - var(--mesAva-width)) / 2)就是和头像宽度同步 */

    /* ▶DIY文字相关◀ */
    --DIY-text1: 'Shall I compare thee to a summer\'s day?\A Thou art more lovely and more temperate.';  /* 上面的DIY文字内容 */
    --topDIY-top: 24px;  /* 顶部DIY文字上下 */
    --DIY-text2: 'Thy eternal summer\A shall not fade nor lose its fair.';  /* 下面的DIY文字内容 */
    --DIY-fs: 11px;  /* 所有DIY文字大小 */
    --topDIY-color: var(--SmartThemeUnderlineColor);  /* 所有DIY文字颜色 默认跟随下划线 */
    --DIY-line-height: 1.6;  /* 所有DIY文字行高 */

    /* ▶More|Edit(原小铅笔) 日期◀ */
    --Edit-fs: 15px;  /* More|Edit文字大小 */
    --chnameright-color: var(--SmartThemeUnderlineColor);  /* 文字颜色默认跟随下划线 */
    --timestamp-top: 32px;  /* 日期上下 */
    --bottomDIY-top: 50px;  /* 日期下面的DIY文字上下 */

    /* ▶思维链相关◀ */
    --thinking-top: 24px;  /* 思维链上下 */
    --thinking-color: rgba(255, 255, 255, 0.5);  /* 思维链颜色 */

    /* ▶底栏&顶栏相关◀ */
    --send-border-radius: 12px;  /* 底栏圆角大小 */
    --send-bg-color: var(--SmartThemeBotMesBlurTintColor);  /* 底栏颜色 默认跟随AI消息颜色 */
    --tb-icon-fs: 16px;  /* 顶栏&底栏图标大小 */
    --tb-icon-color: var(--mycolor);  /* 顶栏&底栏图标颜色 */
    --top-icon-opacity: 0.5;  /* 顶栏图标透明度 */

    --myblur: blur(calc(var(--SmartThemeBlurStrength)));
    --myred: rgb(173, 72, 72);
    --myblack: rgb(40, 40, 40);
    --black30a: rgba(185, 185, 185, 0.3);
    --mybutton: color-mix(in srgb, var(--mycolor), white 85%);  /* 按钮颜色 */
    --field-bg-color: hsl(from var(--mycolor) h 32% 94%);  /* 所有选择框、文本框、勾选框、范围块区域颜色 */
    --myhit: color-mix(in srgb, var(--mycolor), white 45%);
    --mylight: color-mix(in srgb, var(--mycolor), white 65%);
    --mypopbkg: color-mix(in srgb, var(--mycolor), white 95%);
    --popup-backdrop: color-mix(in srgb, var(--mycolor), transparent 98%);
    --myqrbg: color-mix(in srgb, var(--mycolor), white 85%);  /* qr背景颜色 */
    --worldentry-button: 10px;
    --worldentry-button-top: 56px;
    --worldentry-button-select: 64%;

    --big-avatar-height-factor: 1.1;
    --big-avatar-width-factor: 1.1;
}

@media screen and (min-width: 1000px) {
    :root{
        --text-padding-lr: calc((var(--sheldWidth) - var(--mesAva-width)) / 2);  /* 💻pc正文文本与气泡左右边缘距离 */
        --mesAva-width: 82%;  /* 💻pc头像宽度 其实也就是等比例修改大小 */
        --name-left: auto;  /* 💻pc名字左右 */
        --chnameright-padding: calc((var(--sheldWidth) - var(--mesAva-width)) / 2);
    }

    .fillLeft,
    .fillRight {
        min-width: 300px !important;  /* 💻pc预设窗口宽度 */
    }
}

/* 滚动条 */
html, body {
    overflow-x: hidden !important;
}

#chat {
    max-width: 100vw !important;
    overflow-y: auto;
}

* {
    text-shadow: none !important;
    -webkit-tap-highlight-color: transparent !important;

    scrollbar-width: thin;
    scrollbar-color: var(--mycolor) transparent;
}
::-webkit-scrollbar {
    width: 3px !important;
    height: 3px !important;
}
::-webkit-scrollbar-thumb {
    background: var(--mycolor) !important;
    border-radius: 3px !important;
}
::-webkit-scrollbar-track {
    background: transparent !important;
}

/* ===== 全局样式结束 ===== */

/* ===== 气泡 ===== */

/* 去除上下文消息断点横线 */
.lastInContext {
    border-top:none !important;
}

#chat {
    position: relative;
    bottom: 0px;
    max-height: calc(100vh - calc(var(--topBarBlockSize) )) !important;
    background-color: transparent !important;
    padding: 0 0 var(--mes-bottom);
    border: none !important;
    backdrop-filter: none;
}

#chat .mes {
    display: block;
    position: relative;
    border: none;
    border-radius: var(--mes-border-radius);
    padding: 0 0 2px !important;  /* 第三个值是气泡输出完文字后的剩余空间 改mes_text的padding-bottom和这个都可以 */
    width: var(--sheldWidth);
    margin: 0 auto var(--mesandmes) !important;
    backdrop-filter: var(--myblur);
}

#chat .mes::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 200px;  /* 自定义顶部背景的高度 */
    border-radius: var(--mes-border-radius);

    background-image: 
    /* 油画布纹理图↓ */
    url('https://www.transparenttextures.com/patterns/dark-denim-3.png'), 
    /* 白色遮罩，0.4是透明度，使背景变淡不突出，要想变深就改小↓ */
    linear-gradient(rgba(255,255,255,0.4), rgba(255,255,255,0.4)),
    /* ▶你的自定义背景图改这里↓↓↓◀ */
    url('https://i.postimg.cc/DwBSN73q/222pinktopbg.jpg');

    background-blend-mode: screen, normal, normal;

    background-size: auto, 100% 100%, 100% auto; 
    background-position: 0 0, 0 0, center 74%;  /* ▶你的自定义背景图显示的区域改这里的%◀ */
    background-repeat: repeat, no-repeat, no-repeat;

    -webkit-mask-image: linear-gradient(to bottom, black 40%, transparent 100%);
    mask-image: linear-gradient(to bottom, black 40%, transparent 100%);

    filter: contrast(100%) brightness(100%);  /* 提亮你导入的背景图 如果不需要可以删除 */
}

/* 顶部DIY文字 */
#chat .mes::after {
    content: var(--DIY-text1);
    display: block;
    text-align: right;
    position: absolute;
    top: var(--topDIY-top);
    right: var(--chnameright-padding);
    width: 90%;
    color: var(--topDIY-color);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    font-size: var(--DIY-fs);
    line-height: var(--DIY-line-height);
    white-space: pre-wrap; 
}

#chat .mes .mes_block {
    margin-left: 0px !important;
    padding-left: 0px !important;
    overflow: visible;
}

#chat .mes_text {
    padding: var(--text-padding-top) var(--text-padding-lr) var(--text-padding-bottom);
    line-height: 1.6;
}

/* 头像 */
#chat .mesAvatarWrapper {
    position: relative;
    display: block; 
    text-align: center;
    width: 100% !important;
    margin: var(--ava-top) 0 0 !important;
    padding: 0px !important;
    left: 50% !important;
    font-size: 0 !important;
    transform: translateX(-50%) !important;
}

.last_mes .mesAvatarWrapper {
    padding-bottom: 0px !important;
}

#chat .mesAvatarWrapper .avatar {
    display: block;
    width: var(--mesAva-width) !important;
    border-radius: var(--ava-border-radius);
    aspect-ratio: var(--ava-ratio);
    height: auto;
    margin: 0 auto;
    overflow: hidden;
    pointer-events: none !important;
}

#chat .mes .avatar img {
    width: 100%;
    height: 100%;
    border: var(--ava-border-w) solid var(--ava-border-color);
    border-radius: var(--ava-border-radius);
    box-shadow: none;
    object-fit: cover;
    object-position: center var(--ava-area);
    transform-origin: center center; 
}

.zoomed_avatar .panelControlBar {
    opacity: 1;
}

/* 楼层 计时 tokens */
.mes .mesIDDisplay,
.mes .mes_timer,
.mes .tokenCounterDisplay {
    display: inline-flex !important;
    align-items: center !important;
    vertical-align: middle;
    padding: var(--IdTimerToken-top) 0;
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    font-size: var(--IdTimerToken-fs) !important;
    color: var(--IdTimerToken-color); 
    white-space: nowrap;
    opacity: 1;
}

#chat .mesAvatarWrapper::after {
    content: "";
    display: block;
    width: var(--line-width);
    border-bottom: 1px solid var(--IdTimerToken-color);
    margin: var(--line-top) auto;
}

.mes_timer:not(:empty)::before,
.tokenCounterDisplay:not(:empty)::before {
    content: "//";  /* 可以改成自己喜欢的字符 */
    padding: 0 var(--IdTimerToken-between) !important;  /* 控制 // 左右文字的距离 */
    color: var(--IdTimerToken-color);
    font-size: calc(var(--IdTimerToken-fs) + 2px);
    font-weight: bold;
}
.mes_timer:empty,
.mes_timer[style*="display: none"] {
    display: none !important;
}

#chat .mesAvatarWrapper .mesIDDisplay,
#chat .mesAvatarWrapper .mes_timer,
#chat .mesAvatarWrapper .tokenCounterDisplay {
    position: static !important;
    transform: none !important;
    margin-top: 0 !important;
}

#chat .ch_name {
    position: relative !important;
    display: block; 
    min-height: 76px;  /* 名字和右侧元素的总高度 */
    margin-bottom: 10px;
    padding: 8px var(--chnameright-padding) 0 !important;
}
#chat .ch_name > .flex-container {
    display: block !important;
}

/* 名字 */
#chat .name_text {
    display: block;
    text-align: left;
    position: absolute;
    left: var(--name-left);
    top: var(--name-top);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    font-size: var(--name-fs) !important;
    color: var(--name-color);
    max-width: var(--name-width);
    white-space: pre-wrap !important;
    word-break: break-all !important;
    z-index: 2;
}

#chat .name_text::before {
    content: "";
    position: absolute;
    left: var(--namebefore-left);
    bottom: var(--namebefore-top);
    width: var(--namebefore-width);
    height: var(--namebefore-height);
    background-color: var(--namebefore-color);
    z-index: -1;
}

/* 小铅笔 */
.mes_buttons, .extraMesButtons {
    gap: 6px;
    padding: 2px 0;
    overflow: hidden !important; 
}

.mes_button {
    opacity: 1;
    color: var(--chnameright-color);
    filter: none !important;
    padding: 0;
}

.extraMesButtons>div {
    color: var(--chnameright-color);
    filter: none !important;
    padding: 0 0.2em;
}

#chat .ch_name:has(.mes_edit_buttons[style]:not([style*="none"])) .timestamp,
#chat .ch_name:has(.mes_edit_buttons[style]:not([style*="none"]))::after {
    transform: translateY(10px) !important; 
}

#chat .mes .fa-ellipsis-h:before, 
#chat .mes .fa-ellipsis:before {
    content: 'More';
    font-size: var(--Edit-fs);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    border-right: 1px solid var(--chnameright-color);
    padding: 0 6px 0 0;  /* 要和上面的gap一样 */
}
#chat .mes .fa-pencil-alt:before, 
#chat .mes .fa-pencil:before {
    content: 'Edit';
    font-size: var(--Edit-fs);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    padding: 0;
}

#chat .extraMesButtons {
    align-items: center !important; 
    white-space: nowrap;
    transform: translateY(-4px) !important;
}

#chat .mes .reasoning_edit_textarea,
#chat .mes #curEditTextarea {
    background-color: hsl(from var(--mycolor) h 24% 89%);  /* 小铅笔点开的文字区域 */
}
select:focus-visible, input:focus-visible, textarea:focus-visible {
    outline: none;
}

/* 日期 */
#chat .ch_name .timestamp {
    position: absolute;
    right: 0;
    top: var(--timestamp-top);
    margin-right: var(--chnameright-padding);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    font-size: var(--DIY-fs) !important;
    color: var(--chnameright-color);
    opacity: 1;
}

/* 日期下自定义文字 */
#chat .ch_name::after {
    content: var(--DIY-text2);
    display: block;
    text-align: right;
    width: 60%;
    margin-right: var(--chnameright-padding);
    position: absolute;
    right: 0;
    top: var(--bottomDIY-top);
    font-family: var(--font-second);
    font-weight: var(--font-second-weight) !important;
    font-size: var(--DIY-fs);
    color: var(--chnameright-color);
    line-height: var(--DIY-line-height);
    white-space: pre-wrap; 
}

/* 模型图标(?) */
.mes_block .icon-svg {
    position: absolute;
    top: -24px;  /* 模型图标上下 */
    right: var(--text-padding-lr);  /* 模型图标左右 */
    opacity: 0.3;
    z-index: 1;
}

/* 思维链 */
.mes_reasoning_details {
    margin: var(--thinking-top) var(--text-padding-lr) 6px;
}

.mes_reasoning_details .mes_reasoning_summary {
    position: relative;
    display: block;
    margin-right: var(--text-padding-lr);
}

.mes_reasoning_details .mes_reasoning {
    color: hsl(from var(--reasoning-body-color) h calc(s * var(--reasoning-saturation)) calc(l * 0.85));
}

.mes_reasoning_details[open] .mes_reasoning_summary .mes_reasoning_actions {
    position: absolute;
    right: 0px;
    top: 50%;
    transform: translateY(calc(-50% + 0.5em)); 
    margin: 0;
    gap: 12px;
    padding-left: 10px;
    border-left: 1px solid rgba(0,0,0,0.06);
    font-size: var(--Edit-fs);
    filter: none;
}
.mes_reasoning_summary .mes_reasoning_actions .mes_reasoning_edit::before {
    content: "\f303" !important;
    font-family: "Font Awesome 6 Free" !important;
    font-weight: 900 !important;
}

.mes_reasoning_actions .edit_button {
    height: 1.8rem;
    border: none;
    margin: 0;
    font-size: var(--Edit-fs);
    filter: none;
}

.mes_reasoning_header_block {
    width: 100%;
    justify-content: flex-start;
    padding: 0;
    margin: 0 0 8px;
}

.mes_reasoning_header {
    position: relative;
    padding: 8px 24px 8px 32px;
    background: var(--thinking-color);
    border: none;
    border-radius: 0;
    align-items: center;
    margin: 0.5em 0 0;
    backdrop-filter: blur(2px);
}

.mes_reasoning_header::before {
    content: "";
    position: absolute;
    left: 0;
    top: 20%;
    height: 60%;
    width: 4px;
    background: var(--namebefore-color);
    border-right: 1px solid var(--chnameright-color);
    opacity: 0.7;
}
.mes_reasoning_header_title {
    font-size: 0 !important;
}
.mes_reasoning_header_title::before {
    content: "REASONING";  /* 上方悬浮小字 */
    position: absolute;
    top: -4px;
    left: 32px;
    font-size: 8px;
    font-family: sans-serif;
    font-weight: 300;
    letter-spacing: 2.5px;
    color: var(--chnameright-color);
    opacity: 0.6;
}
.mes_reasoning_header_title::after {
    content: "十四行诗 /";  /* 思维链文字 */
    font-size: 13px;
    font-family: var(--font-second);
    font-weight: 700;
    color: var(--SmartThemeBodyColor);
    letter-spacing: 0.15em;
}

.mes_reasoning_arrow {
    color: var(--chnameright-color);
    font-size: 9px !important;
    opacity: 0.7;
    text-align: center;
}

.reasoning_edit_textarea {
    margin: 24px 0 0;
}

.swipe_right, .swipe_left {
    height: auto;
    font-size: 14px;
}

/* 删除消息 */
#chat .mes.selected {
    background-color: var(--SmartThemeBotMesBlurTintColor);
    border: 3px solid var(--myred);
}
#chat .mes[is_user="true"].selected {
    background-color: var(--SmartThemeUserMesBlurTintColor);
    border: 3px solid var(--myred);
}

/* 引用文本 */
.mes_text q {
    background: radial-gradient(circle at center, 
    color-mix(in srgb, var(--SmartThemeQuoteColor) 12%, transparent) 0%, 
    color-mix(in srgb, var(--SmartThemeQuoteColor) 5%, transparent) 100%);
    padding: 2px;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    line-height: 1.8;
}

/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
    position: relative;
    background: linear-gradient(110deg, #ffffff 0%, color-mix(in srgb, var(--SmartThemeQuoteColor) 15%, #fff) 100%);
    padding: 35px 45px;
    border: none !important;
    border-radius: 2px;
    box-shadow: 0 3px 8px rgba(0,0,0,0.08);
    color: var(--SmartThemeQuoteColor);
    font-style: italic;
}
.mes_text blockquote::before, 
.mes_reasoning blockquote::before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(135deg, rgba(255,255,255,0.8) 0%, transparent 40%);
    pointer-events: none;
}
.mes_text blockquote::after, 
.mes_reasoning blockquote::after {
    content: "“";
    position: absolute;
    top: 15px; 
    left: 15px;
    font-size: 3.8rem;
    color: color-mix(in srgb, var(--SmartThemeQuoteColor) 32%, transparent);
    font-family: "Georgia", serif;
    line-height: 1;
}

/* 小幽灵 */
.mes_ghost {
    position: absolute;
    left: var(--text-padding-lr);
    font-size: 18px;
}

/* 文档模式 */
body.documentstyle #chat .mes::before,
body.documentstyle #chat .mes::after,
body.documentstyle #chat .ch_name::after {
    display: none;
}
body.documentstyle #chat .mes {
    background-color: var(--SmartThemeBotMesBlurTintColor);
    margin-bottom: 0px !important;
    border-bottom: 1px dashed var(--SmartThemeQuoteColor);
    border-radius: 0;
    padding: 8px 0 !important;
}
body.documentstyle #chat .mes .mes_block {
    margin-right: 0 !important;
}
body.documentstyle #chat .mes_block .ch_name {
    margin-bottom: 0 !important;
    padding: 0 !important;
}
body.documentstyle #chat .mes .mes_text {
    margin-left: 0 !important;
    padding: 20px var(--text-padding-lr) !important;
}
