/* ===== 首页结束 ===== */

/* ===== 公共样式 ===== */

/* 去除某些高亮 */
a:focus-visible {
    filter: none !important;
}

.custom-drawer-icon, 
.inline-drawer-icon {
    filter: none;
}

/* 展开/合上按钮 */
.fa-chevron-circle-down:before,
.fa-circle-chevron-down:before,
.fa-chevron-circle-up:before, 
.fa-circle-chevron-up:before {
    color: color-mix(in srgb, var(--mycolor), white 35%);

}
.fa-chevron-circle-down:before, .fa-circle-chevron-down:before {
    content: "\f0d7";
}
.fa-chevron-circle-up:before, .fa-circle-chevron-up:before {
    content: "\f0d8";
}

/* ----- button开始 ----- */
.menu_button {
    background-color: var(--mybutton);
    color: var(--mycolor);
    padding: 5px 6px;
    box-shadow: none;
    border: none;
    border-radius: 6px;
    filter: none;
    transition: background-color 0.15s ease;
    outline: none;
}
.menu_button.menu_button_default, 
.menu_button.popup-button-ok,
#dialogue_del_mes_ok {
    background-color: var(--myblack);
    color: var(--mycolor);
    border: none !important;
}
.menu_button.popup-button-cancel {
    background-color: var(--black30a);
}
.red_button, .redWarningBG {
    background-color: var(--mybutton) !important;
    color: color-mix(in srgb, var(--myred), white 40%) !important;
}
.menu_button[disabled], .menu_button.disabled {
    filter: grayscale(1);
}

/* 弹框btn控制 */
.popup-controls {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    justify-content: center;
    align-items: center;
    gap: 8px;
    width: 100%;
    overflow: visible;
    margin-top: 2px;
    padding: 8px 2px;
}
.popup-controls .menu_button,
.vfm__content .menu_button{
    white-space: nowrap;
    flex: 1 1 0;
    max-width: 120px;
    font-size: 13px;
    padding: 6px 12px;
    box-sizing: border-box;
}

/* 删除消息btn控制 */
#dialogue_del_mes .menu_button {
    margin-left: 12px;
    margin-right: 12px;
    padding: 3px 24px;
}
/* 删除消息btn控制 */
#dialogue_del_mes .menu_button {
    margin-left: 12px;
    margin-right: 12px;
    padding: 3px 24px;
}
/* mes铅笔下btn */
.mes_edit_buttons {
    filter: none !important;
}
.mes_reasoning_edit_done, 
.mes_edit_done.menu_button {
    background-color: color-mix(in srgb, var(--mycolor), white 60%);
}
.mes_reasoning_edit_cancel, 
.mes_edit_cancel.menu_button {
    background-color: var(--myblack);
}
.mes_edit_buttons .menu_button, 
.mes_reasoning_actions .edit_button {
    opacity: 0.8;
}

/* 优化双端button */
.menu_button:not(.disabled):not([disabled]):active {
    background-color: var(--myhit) !important;
    transition: none !important;
}

@media (hover: hover) {
    .menu_button:not(.disabled):not([disabled]):hover:not(:active) {
        background-color: var(--myhit);
        cursor: pointer;
    }

    .menu_button.menu_button_default:hover:not(:active),
    .menu_button.popup-button-ok:hover:not(:active) {
        background-color: var(--myhit) !important;
    }
}

@media (hover: none) {
    .menu_button:focus, 
    .menu_button:hover {
        background-color: var(--mybutton) !important; 
        color: var(--mycolor) !important;
    }

    .menu_button.menu_button_default:focus, .menu_button.menu_button_default:hover,
    .menu_button.popup-button-ok:focus,
    .mes_reasoning_edit_cancel:focus, .mes_reasoning_edit_cancel:hover, 
    .mes_edit_cancel.menu_button:focus, .mes_edit_cancel.menu_button:hover {
        background-color: var(--myblack) !important;
        color: var(--mycolor) !important;
    }
    .mes_reasoning_edit_cancel:focus, .mes_reasoning_edit_cancel:hover, 
    .mes_edit_cancel.menu_button:focus, .mes_edit_cancel.menu_button:hover {
        opacity: 0.8;
    }
}

.menu_button, 
.menu_button:focus, 
.menu_button:active, 
.menu_button:focus-visible,
.menu_button_default,
.menu_button_default:focus {
    outline: none !important;
}

.menu_button.active:not(:active) {
    background-color: inherit;
}

a:hover {
    filter: none;
}

/* ----- button结束 ----- */

/* 文本框 */
input,
.text_pole,
textarea,
.reasoning_edit_textarea, 
.edit_textarea {
    background-color: var(--field-bg-color);
    border-radius: 8px;
    border: none;
}
input::placeholder,
.text_pole::placeholder,
textarea::placeholder {
    color: rgba(var(--SmartThemeBodyColor), 0.6) !important;
}
/* 常见最大化文字区域背景颜色 css填入/user描述/char描述/世界书 */
textarea.maximized_textarea[data-for="customCSS"],
textarea.maximized_textarea[data-for="persona_description"],
textarea.maximized_textarea[data-for="description_textarea"],
textarea.maximized_textarea[data-for="firstmessage_textarea"],
textarea.maximized_textarea[data-for^="world_entry_content_"]  {
    background-color: var(--mypopbkg) !important;
}

/* select框 */
select {
    background-color: var(--field-bg-color);
    outline: none;
    border-radius: 8px;
    border: none;
    scrollbar-width: none;
    -ms-overflow-style: none;
}
select option {
    background-color: var(--field-bg-color) !important;
    color: var(--SmartThemeBodyColor) !important;
}
select:active {
    background-color: var(--field-bg-color);
    transition: none;
}
select::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
}

/* 提示框 */
.toast-top-center {
    top: 12px;
}
#toast-container>div {
    background-color: var(--myblack) !important;
    color: hsl(from var(--mycolor) h 38% 85%) !important;
    border-radius: 14px;
    border: none;
    -webkit-box-shadow: none;
    box-shadow: none;
    padding: 14px 10px 14px 48px !important;
}
#toast-container>div:hover {
    -webkit-box-shadow: none;
    box-shadow: none;
}

#toast-container>.toast-success,
#toast-container>.toast-error,
#toast-container>.toast-info,
#toast-container>.toast-warning {
    background-image: none !important; 
}
#toast-container > .toast-success::before,
#toast-container > .toast-error::before,
#toast-container > .toast-info::before,
#toast-container > .toast-warning::before {
    font-family: "Font Awesome 6 Free"; 
    font-weight: 900;
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 20px;
    color: hsl(from var(--mycolor) h 38% 85%);
}
#toast-container > .toast-success::before {
    content: "\f52d"; 
}
#toast-container > .toast-error::before {
    content: "\f086"; 
}
#toast-container > .toast-info::before {
    content: "\f0e0"; 
}
#toast-container > .toast-warning::before {
    content: "\f654"; 
}

/* 弹出框 */
.popup {
    background-color: var(--mypopbkg);
    box-shadow: 0 2px 8px 2px rgba(0, 0, 0, 0.06);
    padding: 4px 8px;
}

/* 勾选框 */
.checkbox_label {
    align-items: center !important;
}
input[type='checkbox'] {
    outline: none;
    background-color: var(--field-bg-color);
    width: calc(var(--mainFontSize) + 6px) !important;
    height: calc(var(--mainFontSize) + 6px) !important;
    border: none;
    box-shadow: none;
    transform: none;
    filter: none;
}
input[type="checkbox"]::before {
    box-shadow: none !important; 
    background-color: var(--SmartThemeQuoteColor);
}

/* 范围块 */
input[type="range"] {
    background: var(--field-bg-color) !important;
    box-shadow: none;
    filter: none;
}
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 20px;
    height: 6px;
    background-color: color-mix(in srgb, var(--mycolor) 60%, white);
    border-radius: 6px;
    cursor: pointer;
    border: none;
    box-shadow: 0 1px 3px 1px color-mix(in srgb, var(--mycolor) 22%, transparent);
}
.range-block-counter input {
    background-color: var(--field-bg-color);
    border: none;
    border-radius: 8px;
}
input[type="range"],
.neo-range-slider:hover, 
input[type="range"]:hover {
    filter: none !important;
}
.neo-range-slider:focus-visible, 
input[type="range"]:focus-visible {
    outline: none !important;
}
.neo-range-slider {
    box-shadow: none !important;
}
.neo-range-input {
    background-color: var(--field-bg-color);
    box-shadow: none;
    padding-left: 0;
}

/* ----- 抽屉内样式开始 ----- */
.drawer-content {
    border: 0 !important;
    border-radius: 0 0 10px 10px;
    box-shadow: none !important;
    transform: translateZ(0);
}

.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    position: relative;
    border: 0 !important;
    border-radius: 4px;
    background-image: none;
    background: linear-gradient(to right, #ffffff 0%, #ffffff 20%, transparent 100%);
    padding: 6px 5px 6px 10px !important;
    filter: drop-shadow(0 4px 6px rgba(0,0,0,0.12)) !important; 

    backface-visibility: hidden;
    transform: translateZ(0); 
    will-change: filter;
}
.inline-drawer-header::before,
#extensions_settings .inline-drawer-toggle.inline-drawer-header::before, 
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header::before, 
#user-settings-block h4::before,
.standoutHeader::before {
    content: '';
    position: absolute;
    left: 0;
    top: 20%;
    bottom: 20%;
    width: 3px;
    background-color: var(--mycolor);
    box-shadow: 0 1px 3px 1px color-mix(in srgb, var(--mycolor) 22%, transparent);
}
#rm_extensions_block #extensions_settings .inline-drawer-icon::before {
    display: none;
}
#rm_extensions_block #extensions_settings2 .inline-drawer-icon::before {
    display: none;
}

/* 优化抽屉 */
@media (hover: hover) {
    .inline-drawer-toggle.inline-drawer-header:hover, 
    .standoutHeader.inline-drawer-header:hover {
        background-color: transparent;
    }
}
.inline-drawer-header,
.standoutHeader.inline-drawer-header,
.inline-drawer-header:focus,
.inline-drawer-header:focus-visible {
    outline: none !important;
    -webkit-tap-highlight-color: transparent !important;
}

/* ----- 抽屉内样式结束 ----- */

/* 分割线 */
hr {
    background-image: none;
    border: none;
    position: relative;
    width: 100%;
    height: 1px;
    background-color: var(--black30a);
    margin: 10px auto !important;
    opacity: 1;
}
hr::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    width: 60px;
    height: 1px;
    background-color: var(--mycolor);
}

.mes_text hr {
    opacity: 0.8;
}

/* input's radio 单选框 预设继续后缀*/
input[type="radio"] {
    accent-color: var(--mycolor);
}

/* code */
.mes_text pre code, 
.mes_reasoning pre code,
code {
    background: #ffffff;
    padding: 2px 4px;
    color: var(--SmartThemeBodyColor);
    border: none;
    border-left: 2px solid var(--mycolor) !important;
    border-radius: 0;
    box-shadow: 0 1px 4px 1px rgba(0,0,0,0.08);
    line-height: 1.6;

    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}

/* 左边框提示条 高级格式化设置+正则+user卡 */
.info-block {
    border: none;
}
.info-block.warning,
.info-block.info,
.info-block.hint  {
    background-color: var(--black30a);
}
.info-block i {
    color: var(--mycolor);
}

/* 处理br */
.mes_text hr + br {
    display: none !important;
}

/* ===== 公共样式结束 ===== */

/* ===== 加载页 ===== */

#load-spinner {
    color: var(--mycolor);
}

.transparent_dialogue_popup {
    background-color: transparent !important;
    box-shadow: none !important;
}
dialog:has(#loader)[open]::backdrop {
    background-color: #101010;
}
.popup[open]::backdrop {
    background-color: var(--popup-backdrop);
}

#loader .splash-logo,
#loader h2 {
    display: none !important;
}

/* ===== 加载页结束 ===== */

/* ----- 移动端世界书 ----- */
