        display: none;
    }

    #world_popup .flex-container #world_editor_select {
        margin-bottom: 0;
    }

    .paginationjs-pages ul li a {
        color: var(--mycolor);
        border: none !important;
    }

    .standoutHeader~.inline-drawer-content {
