        display: flex;
        flex-direction: column;
        align-items: flex-start;
    }
    .WIEnteryHeaderControls > .world_entry_form_control:not([name="PositionBlock"]) {
        flex: 1;
        min-width: 0;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
    }

    input[name="depth"][style*="visibility: hidden"] {
        visibility: visible !important;
