        opacity: 0.7 !important;
    }
    .world_entry_form_control label[for="depth"] {
        visibility: visible !important;
    }

    .world_entry_edit div[name="keywordsAndLogicBlock"] {
        margin-top: 16px;
        border-top: 1px dashed var(--mycolor);
    }

    .disabledWIEntry,
    .disabledWIEntry:not(input):hover,
    .disabledWIEntry:not(input):focus-visible {
        opacity: 0.4;
        filter: grayscale(0.4);
    }
}
